import{_ as r,o as e,c as o,ag as d}from"./chunks/framework.CtWPcAmt.js";const g=JSON.parse('{"title":"3. 个人选型结论","description":"AI Agent 零基础教程","frontmatter":{"title":"3. 个人选型结论","description":"AI Agent 零基础教程","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"selection/03-personal-conclusion.md","filePath":"selection/03-personal-conclusion.md","lastUpdated":null}'),a={name:"selection/03-personal-conclusion.md"};function l(i,t,n,s,h,u){return e(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="_3-个人选型结论" tabindex="-1">3. 个人选型结论 <a class="header-anchor" href="#_3-个人选型结论" aria-label="Permalink to &quot;3. 个人选型结论&quot;">​</a></h1><blockquote><p>本文是<strong>作者基于真实任务与实测数据的个人选型示范</strong>，不是普遍推荐。你的结论请用第 2 章决策路径 + 自己的真实任务得出。</p><p>数据来源：2026-08-12 统一基准实测；作者实际使用场景（本教程项目本身）。</p></blockquote><h2 id="_3-1-作者的真实情况" tabindex="-1">3.1 作者的真实情况 <a class="header-anchor" href="#_3-1-作者的真实情况" aria-label="Permalink to &quot;3.1 作者的真实情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>实际情况</th></tr></thead><tbody><tr><td>主要任务</td><td>教程写作（中文文档）、代码项目（本仓库）、跨工具资料整理、横评实测</td></tr><tr><td>数字基础</td><td>有编程经验，能配置 API/模型</td></tr><tr><td>所在地区与支付</td><td>中国大陆，人民币支付为主</td></tr><tr><td>预算敏感度</td><td>中；可接受付费订阅，但不希望成本不可控</td></tr><tr><td>资料边界</td><td>教程资料无敏感数据，但实测中重视「Agent 是否越权读取」</td></tr><tr><td>对变更的态度</td><td>必须能逐文件核对 Agent 改了什么</td></tr></tbody></table><h2 id="_3-2-我的过滤过程-示范第-2-章路径" tabindex="-1">3.2 我的过滤过程（示范第 2 章路径） <a class="header-anchor" href="#_3-2-我的过滤过程-示范第-2-章路径" aria-label="Permalink to &quot;3.2 我的过滤过程（示范第 2 章路径）&quot;">​</a></h2><p><strong>第 1 步硬约束</strong>：Claude 账号受限 → 排除；BYOK 成本不可见但可接受 → ZCode/Hermes 保留；其余托管产品均可用。</p><p><strong>第 2 步任务类型</strong>：我的任务横跨文档写作与代码项目 → 综合型与代码型都在候选。</p><p><strong>第 3 步偏好</strong>：</p><ul><li>需要逐文件核对变更 → 变更维度必须 ≥4（排除变更维度「—」的 TraeWork）；</li><li>介意越权读取 → 边界维度 ≥4（排除 Qoder 的 2 分；QoderWork 同为扩展样本一并排除）；</li><li>不想为每个项目配置 Provider → 托管路径优先（ZCode/Hermes 作备选）；</li><li>需要审阅后提交推送 → Codex 实测支持。</li></ul><p><strong>第 4 步结果</strong>：主 Agent 候选缩小为 <strong>WorkBuddy 与 Codex</strong>。</p><h2 id="_3-3-我的结论-当前版本-2026-08-13" tabindex="-1">3.3 我的结论（当前版本，2026-08-13） <a class="header-anchor" href="#_3-3-我的结论-当前版本-2026-08-13" aria-label="Permalink to &quot;3.3 我的结论（当前版本，2026-08-13）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>我的选择</th><th>理由（回指证据）</th></tr></thead><tbody><tr><td>主 Agent（日常写作与项目管理）</td><td><strong>WorkBuddy</strong></td><td>0 人工介入、中文界面、产物直接渲染、变更 +647/-0 可核对（第 5 章 WorkBuddy 页）；成本按 Credits 且界面可见，方便控制预算；「产物 6 vs 变更 5」不一致我已知晓，会两处核对</td></tr><tr><td>主 Agent（代码/仓库级任务，备选）</td><td><strong>Codex</strong></td><td>六维 5/5/5/5/5 + 审阅支持提交推送，自检覆盖最完整（第 5 章 Codex 页）；成本不可见是已知代价，靠手动查账单</td></tr><tr><td>代码项目快速任务</td><td><strong>Qoder CN</strong></td><td>2:00/¥0.25 效率极高（第 5 章 Qoder 页）；<strong>但只在非敏感项目中使用</strong>——越权读取与自检失真让我不会把边界敏感的工作交给它</td></tr><tr><td>专用工具（自动化/深度配置）</td><td><strong>Hermes Desktop</strong></td><td>四视图 + 唯一自动恢复实证，适合 Harness 与自动化实验（第 5 章 Hermes 页）；非日常主力</td></tr><tr><td>不选择</td><td>Claude、TraeWork、QoderWork、ZCode</td><td>Claude：账号阻断；TraeWork：变更能力未验证，我无法接受；QoderWork：与 Qoder 同类边界问题且未正式纳入；ZCode：门槛与我已选的工具重叠，暂不投入配置成本</td></tr></tbody></table><p><strong>一个重要提醒</strong>：我的选择里有明显的主观权重——我把「边界安全」和「变更可核对」看得比「速度与绝对便宜」更重。如果你的权重不同（例如成本第一），结论会不同：成本第一的读者会选 Qoder 系，速度与省心平衡的读者会选 TraeWork。</p><h2 id="_3-4-三类典型读者的示范结论" tabindex="-1">3.4 三类典型读者的示范结论 <a class="header-anchor" href="#_3-4-三类典型读者的示范结论" aria-label="Permalink to &quot;3.4 三类典型读者的示范结论&quot;">​</a></h2><blockquote><p>以下为基于实测数据的示范，供对照你的情况，<strong>不是对号入座</strong>。</p></blockquote><h3 id="读者-a-零基础、中文办公为主、无编程背景" tabindex="-1">读者 A：零基础、中文办公为主、无编程背景 <a class="header-anchor" href="#读者-a-零基础、中文办公为主、无编程背景" aria-label="Permalink to &quot;读者 A：零基础、中文办公为主、无编程背景&quot;">​</a></h3><ul><li>先试用：<strong>TraeWork CN → WorkBuddy</strong>（第 2 章第 2 步第一梯队）；</li><li>判断点：TraeWork 三模式是否更顺手，还是 WorkBuddy 的产物/diff 更让你安心；</li><li>付费建议：Free 额度用完、确认日常任务量后，再考虑 Lite/Pro 档（TraeWork ¥45–89/月）或 Pro（WorkBuddy $10/月）；</li><li>不碰：ZCode/Hermes（配置门槛）、Claude（账号风险）、Qoder（边界问题对新手不友好）。</li></ul><h3 id="读者-b-代码项目为主、有开发经验" tabindex="-1">读者 B：代码项目为主、有开发经验 <a class="header-anchor" href="#读者-b-代码项目为主、有开发经验" aria-label="Permalink to &quot;读者 B：代码项目为主、有开发经验&quot;">​</a></h3><ul><li>先试用：<strong>Qoder CN（快）→ ZCode CN（变更透明）→ Codex（综合对照）</strong>；</li><li>判断点：能接受 Qoder 的越权读取吗？能接受 ZCode 的配置成本吗？需要审阅提交推送吗？</li><li>付费建议：Qoder 专业版 ¥59/月起步；ZCode 用 GLM Coding Plan 或 BYOK；已有 ChatGPT 订阅直接用 Codex；</li><li>不碰：Hermes 除非要自托管（它是 BYOK 里的高阶选项）。</li></ul><h3 id="读者-c-重视模型自由、自托管、有系统配置经验" tabindex="-1">读者 C：重视模型自由、自托管、有系统配置经验 <a class="header-anchor" href="#读者-c-重视模型自由、自托管、有系统配置经验" aria-label="Permalink to &quot;读者 C：重视模型自由、自托管、有系统配置经验&quot;">​</a></h3><ul><li>先试用：<strong>Hermes Desktop</strong>（四视图 + 自动恢复实证）；</li><li>判断点：Provider 配置是否顺手、模型账单是否可控、能否承担维护责任；</li><li>付费建议：应用开源免费；按需购买 Portal Credits 或使用自有 API；</li><li>备选：ZCode（同一 BYOK 家族，变更统计更细、但自由度和恢复证据不如 Hermes）。</li></ul><h2 id="_3-5-我建议你带走的三句话" tabindex="-1">3.5 我建议你带走的三句话 <a class="header-anchor" href="#_3-5-我建议你带走的三句话" aria-label="Permalink to &quot;3.5 我建议你带走的三句话&quot;">​</a></h2><ol><li><strong>先过滤能不能用，再比较好不好用</strong>——把地区、账号、支付、资料合规放在所有评分之前；</li><li><strong>用你的真实任务复测 1–2 款</strong>，记录六项指标（见第 2 章试用记录表），7 天后数据会替你做决定；</li><li><strong>没有全能第一名</strong>——托管与 BYOK、四种成本单位、单一任务集决定了任何排名都不可信；「适合谁」比「谁最好」更有用。</li></ol><h2 id="_3-6-结论的有效期与后续" tabindex="-1">3.6 结论的有效期与后续 <a class="header-anchor" href="#_3-6-结论的有效期与后续" aria-label="Permalink to &quot;3.6 结论的有效期与后续&quot;">​</a></h2><ul><li>本结论基于 2026-08-12 实测、2026-08-13 截图核验、2026-08-11 价格核验；价格/活动/界面会变，正式决策前核对官方页面（<code>docs/07</code> 清单）；</li><li>benchmark v2（代码任务统一测试、QoderWork 正式纳入）完成后，第 5 章与本表需按新数据修订——届时「代码优先」段的结论可能变化；</li><li>作者会在本教程推进过程中持续更新此页，标注每次更新时间。</li></ul>',25)])])}const b=r(a,[["render",l]]);export{g as __pageData,b as default};
